 en:{library:'Templates',mySpace:'My projects',creativeElements:'Elements',toolkit:'SANA domains',toolkitDesc:'Three domains for structured ideas and connected projects.',heroEyebrow:'From idea to project',heroDescription:'Choose your domain, connect your ideas on a visual canvas, and move from concept to action.',creativity:'Creative',technology:'Technical',business:'Business',services:'Services',databases:'Databases',apis:'APIs',tasks:'Tasks',decisions:'Decisions',ideas:'Ideas',customers:'Customers',value:'Value proposition',channels:'Channels',costs:'Costs',aiRoute:'Start with SANA AI',aiRouteBody:'Open the assisted journey — AI connection is in progress.',templateRoute:'Explore templates',templateRouteBody:'Pick a domain and template, then open your workspace.',chooseTemplate:'SANA templates',allDomains:'All domains',creativeDomain:'Creative domain',technicalDomain:'Technical domain',commercialDomain:'Business domain',canvasHint:'Drag a tool onto the canvas, or click to add it',canvasBlank:'Your canvas is ready. Drag a node here or pick a tool above.',templatesTitle:'Choose your starting point',templatesSubtitle:'Editable templates across all three domains.',aiStartTitle:'Your assisted journey starts here',aiStartNote:'SANA AI has a designed interface, but n8n is not connected yet. Chat is not available.',aiStartSecondary:'Start with a template or build manually until AI is connected.',addNode:'Add node',dragHint:'Drag nodes to move, click to edit',template:'Template',moodboard:'Moodboard',branching:'Dialogue tree',balance:'Character balance',gameTools:'Game tools',gameToolsDesc:'Build narrative choices and compare gameplay stats.',moodboardDesc:'Images, colors and notes that shape your project.',demoWarning:'Demo data stays in this browser only. AI and authentication are not connected.',projectTypes:'Three domains. One workspace.',projectTypesDesc:'Creativity, technology and business — made for every kind of idea.',ready:'Connected to test backend'}
