const REL_TYPES=['CUSTOM','FRIENDSHIP','FAMILY','RIVALRY','PARTICIPATES_IN','VISITS','LIVES_IN','LEADS_TO','PRECEDES','CONNECTED_TO','APPLIES_TO','AFFECTS'];
function parseRoute(){const h=window.location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(h[0]==='studio')return {page:'studio',id:h[1],tab:h[2]||'map'};return {page:h[0]||'home'};}
const dateLabel=(d,lang)=>{try{return new Date(d).toLocaleDateString(lang==='ar'?'ar-SA':'en-GB',{month:'short',day:'numeric'})}catch{return '—'}};
function Logo({small=false,onClick}){return <button className={`logo-lockup logo-symbol-only ${small?'logo-small':''}`} onClick={onClick} aria-label="SANA home"><img src="/sana-mark-original.png" alt="رمز سنا · SANA" /></button>}
function IconButton({children,onClick,label, className='',disabled=false}){return <button type="button" className={`icon-btn ${className}`} onClick={onClick} aria-label={label||'Action'} title={label} disabled={disabled}>{children}</button>}
function Empty({icon:Icon=Sparkles,title,description,action}){return <div className="empty-state"><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{description}</p>{action}</div>}
function SectionTitle({eyebrow,title,description,action}){return <div className="section-heading"><div>{eyebrow&&<span className="eyebrow"><span className="eyebrow-dot"/>{eyebrow}</span>}<h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>}
function Btn({children,onClick,variant='primary',className='',type='button',disabled=false,icon:Icon}){return <button type={type} disabled={disabled} onClick={onClick} className={`btn btn-${variant} ${className}`}>{Icon&&<Icon size={17}/>}<span>{children}</span></button>}
function DomainPill({domain,t}){const group=domainGroup(domain),Icon=group==='technology'?Code2:group==='business'?BriefcaseBusiness:domain==='games'?Gamepad2:BookOpen;return <span className={`domain-pill domain-${group}`}><Icon size={13}/>{t(domain==='games'?'games':group==='creativity'?'creativity':group)}</span>}
function Cover({domain='writing',variant='card',children}){return <div className={`cover cover-${domain} cover-${variant}`}><span className="cover-orbit a"/><span className="cover-orbit b"/><span className="cover-crescent"/><span className="cover-glow"/>{domain==='games'?<Gamepad2 className="cover-symbol" size={43} strokeWidth={1.2}/>:domain==='technology'?<Code2 className="cover-symbol" size={43} strokeWidth={1.2}/>:domain==='business'?<BriefcaseBusiness className="cover-symbol" size={43} strokeWidth={1.2}/>:<BookOpen className="cover-symbol" size={43} strokeWidth={1.2}/>}<span className="cover-star">✦</span>{children}</div>}
function ProjectCard({project,onClick,t,lang,actions}){return <article className="project-card" onClick={onClick} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')onClick()}}><Cover domain={project.domain}/><div className="project-card-body"><div className="card-topline"><DomainPill domain={project.domain} t={t}/><span className="card-date"><Clock3 size={12}/>{dateLabel(project.updatedAt,lang)}</span></div><h3>{project.name}</h3><p>{project.description||'—'}</p><div className="card-bottom"><span><Layers3 size={15}/>{project.elementCount??project.elements?.length??0} {t('elements')}</span><button className="card-open" type="button" onClick={e=>{e.stopPropagation();onClick()}} aria-label={t('openProject')}>{lang==='ar'?<ArrowLeft size={19}/>:<ArrowRight size={19}/>}</button></div></div></article>}
function Stat({icon:Icon,num,label,shade}){return <div className="stat-item"><span className={`stat-icon ${shade}`}><Icon size={20}/></span><div><strong>{num}</strong><small>{label}</small></div></div>}
function Toast({toast,onClose}){if(!toast)return null;return <div className={`toast ${toast.error?'toast-error':''}`} role="status"><span className="toast-mark">{toast.error?<Info size={17}/>:<CheckCircle2 size={17}/>}</span><span>{toast.message}</span><button onClick={onClose} aria-label="Close"><X size={16}/></button></div>}
function Modal({title,subtitle,onClose,children,wide=false,drawer=false}){useEffect(()=>{const fn=e=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[onClose]);return <div className={`modal-backdrop ${drawer?'modal-as-drawer':''}`} onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className={`modal-card ${wide?'modal-wide':''}`} role="dialog" aria-modal="true" aria-label={title}><header className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconButton label="Close" onClick={onClose}><X size={20}/></IconButton></header>{children}</section></div>}
function FormField({label,children,hint}){return <label className="form-field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}

function ProjectModal({t,lang,onClose,onSave,initial,busy}){
 const [name,setName]=useState(initial?.name||''),[description,setDesc]=useState(initial?.description||''),[domain,setDomain]=useState(initial?.domain||'writing');const editing=Boolean(initial?.id);
 return <Modal title={editing?t('updateProject'):t('newProject')} subtitle={t('ideaName')} onClose={onClose}><form className="modal-form" onSubmit={e=>{e.preventDefault();if(name.trim())onSave({name:name.trim(),description:description.trim(),domain,templateId:editing?null:initial?.templateId,lang})}}><FormField label={`${t('projectName')} *`}><input required maxLength={100} autoFocus placeholder={lang==='ar'?'مثل: مدينة أركان':'e.g. The Lost City'} value={name} onChange={e=>setName(e.target.value)}/></FormField><FormField label={t('projectDescription')}><textarea rows={3} maxLength={5000} value={description} onChange={e=>setDesc(e.target.value)} placeholder={t('projectDescription')}/></FormField><div className="form-field"><span>{t('selectDomain')}</span><div className="choice-grid">{[{id:"writing",icon:BookOpen,desc:lang==="ar"?"قصص وشخصيات وعوالم":"Stories & characters"},{id:"games",icon:Gamepad2,desc:lang==="ar"?"حبكات ومغامرات":"Game narratives"},{id:"technology",icon:Code2,desc:lang==="ar"?"أنظمة و APIs":"Systems & APIs"},{id:"business",icon:BriefcaseBusiness,desc:lang==="ar"?"أعمال وخطط":"Business plans"}].map(item=>{const Icon=item.icon;return <button key={item.id} type="button" disabled={editing} className={`choice-tile ${domain===item.id?"selected":""}`} onClick={()=>setDomain(item.id)}><Icon/><strong>{t(item.id)}</strong><small>{item.desc}</small></button>})}</div></div><div className="modal-actions"><Btn variant="ghost" onClick={onClose}>{t('cancel')}</Btn><Btn type="submit" icon={editing?Check:Plus} disabled={busy||!name.trim()}>{editing?t('save'):t('create')}</Btn></div></form></Modal>
}
function ElementModal({t,lang,onClose,onSave,initial,initialType='characters',position,availableTypes=TYPES,busy}){
 const [type,setType]=useState(initial?.type||initialType),[name,setName]=useState(initial?.name||''),[description,setDesc]=useState(initial?.description||''),[role,setRole]=useState(initial?.role||''),[age,setAge]=useState(initial?.age||''),[locationType,setLocationType]=useState(initial?.locationType||''),[eventType,setEventType]=useState(initial?.eventType||''),[presentationOrder,setOrder]=useState(initial?.presentationOrder||1),[chronologicalOrder,setChrono]=useState(initial?.chronologicalOrder||''),[notes,setNotes]=useState(initial?.notes||'');
 return <Modal title={initial?t('editElement'):t('createElement')} subtitle={t('workspaceSubtitle')} onClose={onClose} drawer><form className="modal-form" onSubmit={e=>{e.preventDefault();if(name.trim())onSave(type,{name:name.trim(),description:description.trim(),role,age:Number(age)||undefined,locationType,eventType,presentationOrder:Number(presentationOrder)||1,chronologicalOrder:Number(chronologicalOrder)||undefined,notes,x:position?.x??initial?.x,y:position?.y??initial?.y},initial?.id)}}><FormField label={t('kind')}><select value={type} onChange={e=>setType(e.target.value)} disabled={!!initial}>{availableTypes.map(k=><option key={k} value={k}>{t(k)}</option>)}</select></FormField><FormField label={`${t('name')} *`}><input autoFocus required maxLength={180} value={name} onChange={e=>setName(e.target.value)} placeholder={lang==='ar'?'أعطِ العنصر اسمًا':'Give it a name'}/></FormField><FormField label={t('description')}><textarea rows={3} value={description} onChange={e=>setDesc(e.target.value)} placeholder={t('descPlaceholder')}/></FormField>{type==='characters'&&<div className="form-split"><FormField label={t('characterRole')}><input value={role} onChange={e=>setRole(e.target.value)} placeholder={lang==='ar'?'البطل، المساعد...':'Protagonist, ally...'}/></FormField><FormField label={t('age')}><input type="number" min="1" value={age} onChange={e=>setAge(e.target.value)} placeholder="24"/></FormField></div>}{type==='locations'&&<FormField label={t('placeType')}><input value={locationType} onChange={e=>setLocationType(e.target.value)} placeholder={lang==='ar'?'مدينة، قلعة، مكتبة...':'City, castle, library...'}/></FormField>}{type==='events'&&<><FormField label={t('eventType')}><input value={eventType} onChange={e=>setEventType(e.target.value)} placeholder={lang==='ar'?'اكتشاف، صراع، تحول...':'Discovery, conflict...'}/></FormField><div className="form-split"><FormField label={t('displayOrder')}><input type="number" min="1" value={presentationOrder} onChange={e=>setOrder(e.target.value)}/></FormField><FormField label={t('chronologicalOrder')}><input type="number" min="1" value={chronologicalOrder} onChange={e=>setChrono(e.target.value)}/></FormField></div></> }<FormField label={`${t('notes')} · ${t('optional')}`}><textarea rows={2} value={notes} onChange={e=>setNotes(e.target.value)}/></FormField><div className="modal-actions"><Btn variant="ghost" onClick={onClose}>{t('cancel')}</Btn><Btn type="submit" icon={Check} disabled={busy||!name.trim()}>{t('save')}</Btn></div></form></Modal>
}
function RelationModal({t,lang,project,elements,onClose,onSave,busy}){
 const [source,setSource]=useState(''),[target,setTarget]=useState(''),[type,setType]=useState('CUSTOM'),[label,setLabel]=useState('');const [choices,setChoices]=useState(['CUSTOM']);const [typesBusy,setTypesBusy]=useState(false);useEffect(()=>{if(!source||!target||source===target)return;let active=true;setTypesBusy(true);repository.allowedRelationTypes(project.id,source,target).then(result=>{if(active){setChoices(result.length?result:['CUSTOM']);setType(result.includes('CUSTOM')?'CUSTOM':result[0])}}).catch(()=>{if(active){setChoices(['CUSTOM']);setType('CUSTOM')}}).finally(()=>{if(active)setTypesBusy(false)});return()=>{active=false}},[source,target,project.id]);
 return <Modal title={t('newRelation')} subtitle={lang==='ar'?'حدد عنصرين، ثم نوع الرابطة بينهما':'Choose two elements and how they connect'} onClose={onClose} drawer><form className="modal-form" onSubmit={e=>{e.preventDefault();if(source&&target&&source!==target)onSave({source,target,type,label})}}><FormField label={t('source')}><select required value={source} onChange={e=>setSource(e.target.value)}><option value="">— {t('source')} —</option>{elements.map(e=><option key={e.id} value={e.id}>{e.name} · {t(e.type)}</option>)}</select></FormField><FormField label={t('target')}><select required value={target} onChange={e=>setTarget(e.target.value)}><option value="">— {t('target')} —</option>{elements.filter(e=>String(e.id)!==source).map(e=><option key={e.id} value={e.id}>{e.name} · {t(e.type)}</option>)}</select></FormField><FormField label={t('relationType')}><select value={type} onChange={e=>setType(e.target.value)}>{choices.map(v=><option key={v}>{v}</option>)}</select></FormField><FormField label={`${t('relationLabel')} · ${t('optional')}`}><input maxLength={50} value={label} onChange={e=>setLabel(e.target.value)} placeholder={lang==='ar'?'مثال: يساعدها في الرحلة':'e.g. Helps on the journey'}/></FormField><div className="modal-actions"><Btn variant="ghost" onClick={onClose}>{t('cancel')}</Btn><Btn type="submit" icon={Link2} disabled={busy||typesBusy||!source||!target||source===target}>{t('create')}</Btn></div></form></Modal>
}
function ConfirmModal({t,lang,title,description,onCancel,onConfirm,busy}){return <Modal title={title||t('confirmDelete')} onClose={onCancel}><div className="confirm-panel"><span className="danger-symbol"><Trash2 size={24}/></span><p>{description||t('confirmDelete')}</p><div className="modal-actions"><Btn variant="ghost" onClick={onCancel}>{t('cancel')}</Btn><Btn variant="danger" onClick={onConfirm} disabled={busy} icon={Trash2}>{t('delete')}</Btn></div></div></Modal>}
function Scene({onStart,t}){return <div className="hero-scene" aria-label="SANA creative universe"><div className="scene-arch scene-arch-outer"/><div className="scene-arch scene-arch-inner"/><div className="scene-rays"/><div className="scene-sun"/><div className="scene-hill hill-back"/><div className="scene-hill hill-front"/><div className="scene-stars"><i>✦</i><i>✧</i><i>✦</i><i>✧</i><i>✦</i></div><img className="hero-brand" src="/sana-logo.webp" alt="SANA"/><div className="orbit-card card-one"><Lightbulb size={17}/><span>{t('stepOne')}</span></div><div className="orbit-card card-two"><Network size={17}/><span>{t('stepThree')}</span></div><div className="orbit-card card-three"><Sparkles size={17}/><span>{t('stepFour')}</span></div><span className="scene-caption">SANA · CREATIVE SPACE</span></div>}
function Landing({t,lang,projects,onNavigate,onNew,onOpen,onAI}){
 const total=projects.length,elems=projects.reduce((n,p)=>n+(p.elementCount||0),0);
 return <>
 <section className="landing-hero"><div className="hero-content"><div className="hero-tag"><Sparkles size={15}/>{t('heroEyebrow')}<span className="hero-tag-line"/></div><h1>{t('heroTitleA')}<br/><em>{t('heroTitleB')}</em></h1><p>{t('heroDescription')}</p><div className="hero-route-grid"><button type="button" className="hero-route hero-route-ai" onClick={onAI}><span className="route-icon"><Sparkles size={28}/></span><span className="route-copy"><strong>{t('aiRoute')}</strong><small>{t('aiRouteBody')}</small><span className="route-link">SANA AI <ArrowUpLeft size={18}/></span></span></button><button type="button" className="hero-route hero-route-templates" onClick={()=>onNavigate('library')}><span className="route-icon"><LayoutTemplate size={28}/></span><span className="route-copy"><strong>{t('templateRoute')}</strong><small>{t('templateRouteBody')}</small><span className="route-link">{t('templatesTitle')} <ArrowUpLeft size={18}/></span></span></button></div><div className="hero-mini"><span><Check size={14}/>{lang==='ar'?'ثلاثة مجالات في مكان واحد':'Three domains in one place'}</span><span><Check size={14}/>{lang==='ar'?'أفكارك محفوظة':'Save as you create'}</span></div></div><Scene t={t} onStart={onNew}/><span className="hero-bottom-stamp">EST. 2026 — SANA STUDIO</span></section>
 <section className="main-shell home-main"><div className="welcome-line"><div><span className="eyebrow"><span className="eyebrow-dot"/>{t('mySpace')}</span><h2>{t('goodDay')} <span>✦</span></h2></div><button className="link-action" onClick={()=>onNavigate('projects')}>{t('viewAll')} {lang==='ar'?<ArrowLeft size={18}/>:<ArrowRight size={18}/>}</button></div><div className="stats-panel"><Stat shade="stat-teal" icon={FolderOpen} num={total} label={t('allProjects')}/><Stat shade="stat-gold" icon={Sparkles} num={elems} label={t('creativeElements')}/><Stat shade="stat-rose" icon={Heart} num={lang==='ar'?'∞':'∞'} label={t('yourProgress')}/><div className="stats-note"><Sparkles size={18}/><span>{t('ideaName')}</span></div></div>
 <SectionTitle eyebrow="YOUR WORK" title={t('yourProjects')} description={t('projectsDesc')} action={<Btn variant="soft" icon={Plus} onClick={onNew}>{t('newProject')}</Btn>}/>{projects.length?<div className="projects-grid">{projects.slice(0,3).map(p=><ProjectCard key={p.id} project={p} onClick={()=>onOpen(p.id)} t={t} lang={lang}/>)}</div>:<Empty title={t('noProjects')} description={t('noProjectsBody')} action={<Btn icon={Plus} onClick={onNew}>{t('startProject')}</Btn>}/>}
 <div className="home-duo"><div className="duo-intro"><span className="eyebrow"><span className="eyebrow-dot"/>SANA PROJECT DOMAINS</span><h2>{t('toolkit')}</h2><p>{t('toolkitDesc')}</p><Btn variant="outline-dark" onClick={()=>onNavigate('tools')}>{t('exploreTools')}</Btn><div className="duo-ornament">✳</div></div><div className="duo-tools">{[{type:'characters',sub:'featureStoriesBody'},{type:'worlds',sub:'featureWorldsBody'},{type:'events',sub:'featureMapsBody'}].map(({type,sub})=>{const Icon=ICONS[type];return <button key={type} onClick={()=>onNavigate('tools')}><span className={`tool-tile-icon ${COLORS[type]}`}><Icon size={22}/></span><div><strong>{t(type)}</strong><small>{t(sub)}</small></div>{lang==='ar'?<ArrowUpLeft size={17}/>:<ArrowUpRight size={17}/>}</button>})}</div></div>
 <section className="journey"><SectionTitle eyebrow="HOW IT WORKS" title={t('showcase')} description={t('showcaseDesc')}/><div className="journey-grid">{[{icon:Lightbulb,title:'stepOne'},{icon:PenLine,title:'stepTwo'},{icon:Network,title:'stepThree'},{icon:Sparkles,title:'stepFour'}].map((s,i)=><div className="journey-step" key={s.title}><span className="journey-number">0{i+1}</span><s.icon size={25} strokeWidth={1.6}/><h3>{t(s.title)}</h3><span className="journey-connector"/></div>)}</div></section>
 <section className="bottom-cta"><span className="cta-star cta-star-one">✦</span><span className="cta-star cta-star-two">✧</span><div><span className="eyebrow">A SPARK IS ALL IT TAKES</span><h2>{t('sparkTitle')}</h2><p>{t('sparkBody')}</p></div><Btn onClick={onNew} icon={Plus}>{t('createNow')}</Btn></section></section></>
}
